{
  "service": "search-platform",
  "version": "5.0.0",
  "port": 6060,
  "rate_limiting": {
    "global_enabled": true,
    "mode": "per_ip",
    "endpoints": {
      "/api/search": {
        "enabled": true,
        "requests_per_minute_per_ip": 20,
        "burst": 5
      },
      "/api/users": {
        "enabled": true,
        "requests_per_minute_per_ip": 30,
        "burst": 10
      },
      "/api/products": {
        "enabled": true,
        "requests_per_minute_per_ip": 50,
        "burst": 15
      }
    }
  },
  "search": {
    "engine": "elasticsearch",
    "timeout_ms": 30000,
    "max_results": null,
    "pagination": false,
    "deep_query": true
  },
  "database": {
    "host": "db-platform.internal",
    "port": 5432,
    "pool_size": 40
  }
}
